-- Qualidade tipográfica dos documentos e identidade documental privada/versionada por tenant.
begin;

create table public.organization_document_identities (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  version_no integer not null check(version_no>0),
  logo_bytes bytea,
  logo_mime_type text check(logo_mime_type is null or logo_mime_type in ('image/jpeg','image/png','image/webp')),
  logo_width integer check(logo_width is null or logo_width between 64 and 4096),
  logo_height integer check(logo_height is null or logo_height between 64 and 4096),
  logo_sha256 text check(logo_sha256 is null or logo_sha256 ~ '^[0-9a-f]{64}$'),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique(organization_id,version_no),
  check((logo_bytes is null and logo_mime_type is null and logo_width is null and logo_height is null and logo_sha256 is null) or (logo_bytes is not null and logo_mime_type is not null and logo_width is not null and logo_height is not null and logo_sha256 is not null))
);
create index organization_document_identities_org_idx on public.organization_document_identities(organization_id,version_no desc);

alter table public.organizations add column if not exists current_document_identity_id uuid references public.organization_document_identities(id) on delete set null;
alter table public.real_estate_document_previews add column if not exists document_identity_id uuid references public.organization_document_identities(id) on delete restrict,add column if not exists identity_snapshot jsonb not null default '{}'::jsonb;
alter table public.real_estate_document_versions add column if not exists document_identity_id uuid references public.organization_document_identities(id) on delete restrict,add column if not exists identity_snapshot jsonb not null default '{}'::jsonb;

alter table public.organization_document_identities enable row level security;
alter table public.organization_document_identities force row level security;
create policy organization_document_identities_read on public.organization_document_identities for select to authenticated using(public.current_membership_role(organization_id) in ('owner','manager','agent'));
revoke all on public.organization_document_identities from public,anon,authenticated;
grant select on public.organization_document_identities to authenticated;

create or replace function public.real_estate_document_sentence(target_payload jsonb,target_key text)
returns text language plpgsql immutable security definer set search_path='' as $$
declare value text:=public.real_estate_document_text(target_payload,target_key);
begin
  if right(value,1) ~ '[\.,;:!?]' then return value; end if;
  return value||'.';
end $$;

create or replace function public.real_estate_document_location_text(target_payload jsonb,target_key text)
returns text language sql immutable security definer set search_path='' as $$
  select regexp_replace(public.real_estate_document_text(target_payload,target_key),'[[:space:]\.,;:!?]+$','','g')
$$;

create or replace function public.real_estate_document_date_text(target_payload jsonb,target_key text)
returns text language plpgsql immutable security definer set search_path='' as $$
declare value date; month_name text;
begin
  if coalesce(target_payload->>target_key,'') !~ '^\d{4}-\d{2}-\d{2}$' then return 'Preenchimento necessário'; end if;
  value:=(target_payload->>target_key)::date;
  month_name:=(array['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'])[extract(month from value)::integer];
  return extract(day from value)::integer||' de '||month_name||' de '||extract(year from value)::integer;
end $$;

create or replace function public.real_estate_document_identity_snapshot(target_organization uuid,target_identity uuid default null)
returns jsonb language sql stable security definer set search_path='' as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'organization_name',o.name,'trade_name',o.trade_name,'public_phone',o.public_phone,'public_whatsapp',o.public_whatsapp,'creci',o.creci,'commercial_signature',o.commercial_signature,
    'identity_id',i.id,'identity_version',i.version_no,'logo_mime_type',i.logo_mime_type,'logo_width',i.logo_width,'logo_height',i.logo_height,'logo_sha256',i.logo_sha256
  )) from public.organizations o left join public.organization_document_identities i on i.id=coalesce(target_identity,o.current_document_identity_id) and i.organization_id=o.id where o.id=target_organization
$$;

create or replace function public.document_logo_is_valid(target_logo bytea,target_mime text,target_width integer,target_height integer)
returns boolean language plpgsql immutable security definer set search_path='' as $$
declare size integer:=octet_length(target_logo);position integer;marker integer;segment_length integer;actual_width integer;actual_height integer;
begin
  if size<64 or size>3145728 or target_width not between 64 and 4096 or target_height not between 64 and 4096 then return false; end if;
  if target_mime='image/png' then
    if size<33 or substring(target_logo from 1 for 8)<>decode('89504e470d0a1a0a','hex') or substring(target_logo from size-7 for 8)<>decode('49454e44ae426082','hex') then return false; end if;
    actual_width:=(get_byte(target_logo,16)<<24)+(get_byte(target_logo,17)<<16)+(get_byte(target_logo,18)<<8)+get_byte(target_logo,19);actual_height:=(get_byte(target_logo,20)<<24)+(get_byte(target_logo,21)<<16)+(get_byte(target_logo,22)<<8)+get_byte(target_logo,23);return actual_width=target_width and actual_height=target_height;
  elsif target_mime='image/jpeg' then
    if substring(target_logo from 1 for 3)<>decode('ffd8ff','hex') or substring(target_logo from size-1 for 2)<>decode('ffd9','hex') then return false; end if;
    position:=2;while position+8<size loop if get_byte(target_logo,position)<>255 then position:=position+1;continue;end if;marker:=get_byte(target_logo,position+1);if marker in (192,193,194,195,197,198,199,201,202,203,205,206,207) then actual_height:=get_byte(target_logo,position+5)*256+get_byte(target_logo,position+6);actual_width:=get_byte(target_logo,position+7)*256+get_byte(target_logo,position+8);return actual_width=target_width and actual_height=target_height;end if;if marker in (216,217) or marker between 208 and 215 then position:=position+2;continue;end if;if position+3>=size then return false;end if;segment_length:=get_byte(target_logo,position+2)*256+get_byte(target_logo,position+3);if segment_length<2 then return false;end if;position:=position+2+segment_length;end loop;return false;
  elsif target_mime='image/webp' then
    if size<30 or substring(target_logo from 1 for 4)<>convert_to('RIFF','UTF8') or substring(target_logo from 9 for 4)<>convert_to('WEBP','UTF8') then return false; end if;
    return get_byte(target_logo,4)+get_byte(target_logo,5)*256+get_byte(target_logo,6)*65536+get_byte(target_logo,7)*16777216+8=size;
  end if;
  return false;
end $$;

create or replace function public.set_organization_document_identity(target_organization uuid,target_logo_base64 text default null,target_logo_mime_type text default null,target_logo_width integer default null,target_logo_height integer default null,target_remove boolean default false)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor_role text:=public.current_membership_role(target_organization);logo bytea;next_version integer;created public.organization_document_identities;previous public.organization_document_identities;action_name text;
begin
  if actor_role not in ('owner','manager') then raise exception using errcode='42501',message='DOCUMENT_IDENTITY_ACCESS_DENIED'; end if;
  perform 1 from public.organizations where id=target_organization for update;
  if not found then raise exception using errcode='P0002',message='ORGANIZATION_NOT_FOUND'; end if;
  select i.* into previous from public.organizations o left join public.organization_document_identities i on i.id=o.current_document_identity_id where o.id=target_organization;
  if target_remove then
    logo:=null;target_logo_mime_type:=null;target_logo_width:=null;target_logo_height:=null;
    if previous.id is not null and previous.logo_bytes is null then return public.real_estate_document_identity_snapshot(target_organization,previous.id); end if;
  else
    if target_logo_mime_type not in ('image/jpeg','image/png','image/webp') or target_logo_width not between 64 and 4096 or target_logo_height not between 64 and 4096 or coalesce(char_length(target_logo_base64),0)>4194304 then raise exception using errcode='22023',message='DOCUMENT_LOGO_INVALID'; end if;
    begin logo:=decode(target_logo_base64,'base64'); exception when others then raise exception using errcode='22023',message='DOCUMENT_LOGO_INVALID'; end;
    if not public.document_logo_is_valid(logo,target_logo_mime_type,target_logo_width,target_logo_height) then raise exception using errcode='22023',message='DOCUMENT_LOGO_INVALID'; end if;
    if previous.logo_sha256=encode(extensions.digest(logo,'sha256'),'hex') then return public.real_estate_document_identity_snapshot(target_organization,previous.id); end if;
  end if;
  select coalesce(max(version_no),0)+1 into next_version from public.organization_document_identities where organization_id=target_organization;
  insert into public.organization_document_identities(organization_id,version_no,logo_bytes,logo_mime_type,logo_width,logo_height,logo_sha256,created_by) values(target_organization,next_version,logo,target_logo_mime_type,target_logo_width,target_logo_height,case when logo is null then null else encode(extensions.digest(logo,'sha256'),'hex') end,auth.uid()) returning * into created;
  update public.organizations set current_document_identity_id=created.id where id=target_organization;
  action_name:=case when logo is null then 'document_logo_removed' when previous.logo_bytes is null then 'document_logo_added' else 'document_logo_replaced' end;
  insert into public.audit_events(organization_id,actor_id,entity_type,entity_id,action,metadata) values(target_organization,auth.uid(),'organization_document_identity',created.id,action_name,jsonb_build_object('identity_version',next_version,'mime_type',target_logo_mime_type,'width',target_logo_width,'height',target_logo_height));
  return public.real_estate_document_identity_snapshot(target_organization,created.id);
end $$;

create or replace function public.render_real_estate_document(target_type text,target_payload jsonb)
returns text language plpgsql immutable security definer set search_path='' as $$
declare exclusivity_text text;arras_text text;financing_text text;
begin
  perform public.validate_real_estate_document_payload(target_type,target_payload);
  if target_type='sale_intermediation' then
    exclusivity_text:=case target_payload->>'exclusivity' when 'exclusive' then 'A modalidade escolhida expressamente é EXCLUSIVA. Durante o prazo indicado, os efeitos da exclusividade e a remuneração observarão o que foi ajustado neste documento e a legislação aplicável, inclusive o art. 726 do Código Civil.' when 'non_exclusive' then 'A modalidade escolhida expressamente é NÃO EXCLUSIVA. O contratante poderá atuar por outros meios, e a remuneração observará o resultado da mediação e as demais condições expressamente ajustadas.' else 'Preenchimento necessário: escolher EXCLUSIVA ou NÃO EXCLUSIVA.' end;
    return concat_ws(E'\n\n','AUTORIZAÇÃO / CONTRATO DE INTERMEDIAÇÃO PARA VENDA DE IMÓVEL','1. PARTES','CONTRATANTE: '||public.real_estate_document_sentence(target_payload,'seller_name')||' Contato: '||public.real_estate_document_sentence(target_payload,'seller_contact'),'CONTRATADO: '||public.real_estate_document_text(target_payload,'broker_name')||', CRECI '||public.real_estate_document_sentence(target_payload,'broker_creci')||' Contato: '||public.real_estate_document_sentence(target_payload,'broker_contact'),'2. OBJETO','O contratante autoriza a intermediação da venda do seguinte imóvel: '||public.real_estate_document_sentence(target_payload,'property_description')||' Matrícula/registro, se cadastrado: '||public.real_estate_document_sentence(target_payload,'registry_information'),'3. PREÇO E CONDIÇÕES COMERCIAIS','Preço pretendido: '||public.real_estate_document_sentence(target_payload,'offer_price')||' Condições: '||public.real_estate_document_sentence(target_payload,'commercial_conditions'),'4. MODALIDADE DA INTERMEDIAÇÃO',exclusivity_text,'5. DIVULGAÇÃO',public.real_estate_document_sentence(target_payload,'publicity_authorization'),'6. DEVERES DAS PARTES','O contratado atuará com diligência e prudência, prestando as informações relevantes de que disponha. O contratante prestará informações verdadeiras e disponibilizará os elementos necessários à intermediação.','7. REMUNERAÇÃO',public.real_estate_document_sentence(target_payload,'remuneration_terms'),'8. PRAZO E ENCERRAMENTO','Prazo: '||public.real_estate_document_sentence(target_payload,'term_text')||' Condições de encerramento: '||public.real_estate_document_sentence(target_payload,'closing_terms'),'9. DADOS PESSOAIS','Os dados pessoais serão tratados na medida necessária à execução desta intermediação e ao cumprimento de obrigações legais, com acesso restrito e medidas de segurança compatíveis.','10. LOCAL, DATA E ASSINATURAS',public.real_estate_document_location_text(target_payload,'city')||', '||public.real_estate_document_date_text(target_payload,'document_date')||'.',E'\n________________________________________\nCONTRATANTE',E'\n________________________________________\nCONTRATADO / CORRETOR DE IMÓVEIS');
  elsif target_type='property_sale_purchase' then
    arras_text:=case target_payload->>'arras_option' when 'none' then 'As partes declararam que não há sinal/arras nesta configuração.' when 'applicable' then public.real_estate_document_sentence(target_payload,'arras_terms') else 'Preenchimento necessário: declarar se há sinal/arras.' end;
    financing_text:=case target_payload->>'financing_option' when 'none' then 'As partes declararam que não há financiamento nesta configuração.' when 'applicable' then public.real_estate_document_sentence(target_payload,'financing_terms') else 'Preenchimento necessário: declarar se há financiamento.' end;
    return concat_ws(E'\n\n','CONTRATO PARTICULAR DE COMPRA E VENDA DE IMÓVEL','AVISO DE REVISÃO','Minuta controlada para revisão das partes. As condições juridicamente sensíveis abaixo dependem de preenchimento expresso e de revisão jurídica profissional antes da assinatura.','1. PARTES','VENDEDOR(ES): '||public.real_estate_document_sentence(target_payload,'seller_name')||' Contato: '||public.real_estate_document_sentence(target_payload,'seller_contact'),'COMPRADOR(ES): '||public.real_estate_document_sentence(target_payload,'buyer_name')||' Contato: '||public.real_estate_document_sentence(target_payload,'buyer_contact'),'2. IMÓVEL',public.real_estate_document_sentence(target_payload,'property_description')||' Matrícula/registro, se cadastrado: '||public.real_estate_document_sentence(target_payload,'registry_information'),'3. PREÇO E PAGAMENTO','Preço: '||public.real_estate_document_sentence(target_payload,'price')||' Forma de pagamento e parcelas: '||public.real_estate_document_sentence(target_payload,'payment_terms'),'4. SINAL / ARRAS',arras_text,'5. FINANCIAMENTO',financing_text,'6. POSSE',public.real_estate_document_sentence(target_payload,'possession_terms'),'7. ESCRITURA E TRANSFERÊNCIA',public.real_estate_document_sentence(target_payload,'deed_transfer_terms'),'8. TRIBUTOS E DESPESAS',public.real_estate_document_sentence(target_payload,'taxes_expenses_terms'),'9. DÉBITOS INFORMADOS',public.real_estate_document_sentence(target_payload,'debts_terms'),'10. CORRETAGEM',public.real_estate_document_sentence(target_payload,'brokerage_terms'),'11. INADIMPLEMENTO',public.real_estate_document_sentence(target_payload,'default_terms'),'12. RESCISÃO',public.real_estate_document_sentence(target_payload,'termination_terms'),'13. DADOS PESSOAIS','Os dados pessoais serão tratados apenas na medida necessária à preparação e execução desta relação e ao cumprimento de obrigações legais, com acesso restrito e medidas de segurança compatíveis.','14. LOCAL, DATA E ASSINATURAS',public.real_estate_document_location_text(target_payload,'city')||', '||public.real_estate_document_date_text(target_payload,'document_date')||'.',E'\n________________________________________\nVENDEDOR(ES)',E'\n________________________________________\nCOMPRADOR(ES)',case when nullif(trim(target_payload->>'witnesses'),'') is null then 'TESTEMUNHAS (opcional nesta configuração): Preenchimento necessário' else 'TESTEMUNHAS: '||public.real_estate_document_sentence(target_payload,'witnesses') end);
  end if;
  raise exception using errcode='22023',message='DOCUMENT_INVALID_TYPE';
end $$;

create or replace function public.preview_real_estate_document(target_organization uuid,target_template uuid,target_payload jsonb,target_document uuid default null)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare template public.document_templates;missing text[];preview_id uuid;content text;identity_id uuid;identity jsonb;
begin
  if public.current_membership_role(target_organization) not in ('owner','manager','agent') or not public.can_use_entitlement(target_organization,'crm.documents') then raise exception using errcode='42501',message='DOCUMENT_ACCESS_DENIED'; end if;
  if target_document is not null and not public.can_access_real_estate_document(target_document,target_organization) then raise exception using errcode='42501',message='DOCUMENT_ACCESS_DENIED'; end if;
  select * into template from public.document_templates where id=target_template and status in ('active','legal_review_required');if not found then raise exception using errcode='22023',message='DOCUMENT_TEMPLATE_UNAVAILABLE'; end if;
  perform public.validate_real_estate_document_payload(template.document_type,target_payload);missing:=public.real_estate_document_missing_fields(template.document_type,target_payload);content:=public.render_real_estate_document(template.document_type,target_payload);
  select current_document_identity_id into identity_id from public.organizations where id=target_organization;identity:=public.real_estate_document_identity_snapshot(target_organization,identity_id);
  insert into public.real_estate_document_previews(organization_id,template_id,document_id,actor_id,payload_hash,missing_fields,document_identity_id,identity_snapshot) values(target_organization,target_template,target_document,auth.uid(),public.real_estate_document_payload_hash(target_payload),missing,identity_id,coalesce(identity,'{}')) returning id into preview_id;
  insert into public.audit_events(organization_id,actor_id,entity_type,entity_id,action,metadata) values(target_organization,auth.uid(),'real_estate_document',target_document,'document_previewed',jsonb_build_object('template_code',template.template_code,'template_version',template.version,'missing_count',cardinality(missing),'identity_version',identity->>'identity_version'));
  return jsonb_build_object('preview_id',preview_id,'content',content,'missing_fields',missing,'expires_at',now()+interval '30 minutes','template_code',template.template_code,'template_version',template.version,'document_identity_id',identity_id,'identity_snapshot',identity);
end $$;

create or replace function public.save_real_estate_document_version(target_organization uuid,target_preview uuid,target_payload jsonb,target_document uuid default null,target_property uuid default null,target_owner uuid default null,target_lead uuid default null,target_proposal uuid default null,target_changes_summary text default null)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare preview public.real_estate_document_previews;template public.document_templates;document public.real_estate_documents;version_row public.real_estate_document_versions;actor_role text:=public.current_membership_role(target_organization);next_version integer;
begin
  select * into preview from public.real_estate_document_previews where id=target_preview and organization_id=target_organization and actor_id=auth.uid() and consumed_at is null and expires_at>now() for update;
  if not found or preview.document_id is distinct from target_document or public.real_estate_document_payload_hash(target_payload)<>preview.payload_hash then raise exception using errcode='22023',message='DOCUMENT_PREVIEW_MISMATCH'; end if;
  select * into template from public.document_templates where id=preview.template_id;perform public.validate_real_estate_document_payload(template.document_type,target_payload);perform public.real_estate_document_assert_references(target_organization,target_property,target_owner,target_lead,target_proposal);
  if target_document is null then insert into public.real_estate_documents(organization_id,document_type,property_id,owner_id,lead_id,proposal_id,responsible_user_id,created_by,current_version) values(target_organization,template.document_type,target_property,target_owner,target_lead,target_proposal,auth.uid(),auth.uid(),1) returning * into document;next_version:=1;
  else select * into document from public.real_estate_documents where id=target_document and organization_id=target_organization for update;if not found or not public.can_access_real_estate_document(document.id,target_organization) then raise exception using errcode='42501',message='DOCUMENT_ACCESS_DENIED'; end if;if document.document_type<>template.document_type then raise exception using errcode='22023',message='DOCUMENT_TYPE_MISMATCH'; end if;next_version:=document.current_version+1;update public.real_estate_documents set property_id=target_property,owner_id=target_owner,lead_id=target_lead,proposal_id=target_proposal,current_version=next_version,status='draft',updated_at=now(),finalized_at=null,canceled_at=null where id=document.id returning * into document;end if;
  insert into public.real_estate_document_versions(organization_id,document_id,version_no,template_id,template_code,template_version,data_snapshot,rendered_content,missing_fields,optional_fields,changes_summary,created_by,document_identity_id,identity_snapshot) values(target_organization,document.id,next_version,template.id,template.template_code,template.version,target_payload,public.render_real_estate_document(template.document_type,target_payload),preview.missing_fields,array(select f->>'key' from jsonb_array_elements(template.field_schema) f where coalesce((f->>'required')::boolean,false)=false),nullif(trim(target_changes_summary),''),auth.uid(),preview.document_identity_id,preview.identity_snapshot) returning * into version_row;
  update public.real_estate_document_previews set consumed_at=now(),document_id=document.id where id=preview.id;
  insert into public.audit_events(organization_id,actor_id,entity_type,entity_id,action,metadata) values(target_organization,auth.uid(),'real_estate_document',document.id,case when next_version=1 then 'document_created' else 'document_version_created' end,jsonb_build_object('version',next_version,'template_code',template.template_code,'template_version',template.version,'identity_version',preview.identity_snapshot->>'identity_version'));
  return jsonb_build_object('document_id',document.id,'version_id',version_row.id,'version_no',next_version,'status','draft','missing_fields',preview.missing_fields);
end $$;

revoke all on function public.real_estate_document_sentence(jsonb,text),public.real_estate_document_location_text(jsonb,text),public.real_estate_document_identity_snapshot(uuid,uuid),public.document_logo_is_valid(bytea,text,integer,integer),public.set_organization_document_identity(uuid,text,text,integer,integer,boolean) from public,anon,authenticated;
grant execute on function public.set_organization_document_identity(uuid,text,text,integer,integer,boolean) to authenticated;

-- A logo original fornecida pelo proprietário é instalada somente no tenant interno auditado.
do $$ declare target_org uuid;owner_id uuid;identity_version integer;identity_id uuid;logo bytea:=decode('','base64');begin
  select s.organization_id into target_org from public.subscriptions s where s.is_current and s.provider='internal' and coalesce((s.metadata->>'billing_exempt')::boolean,false) order by s.created_at limit 1;
  if target_org is not null then select m.user_id into owner_id from public.organization_members m where m.organization_id=target_org and m.role='owner' and m.status='active' order by m.created_at limit 1;select coalesce(max(version_no),0)+1 into identity_version from public.organization_document_identities where organization_id=target_org;insert into public.organization_document_identities(organization_id,version_no,logo_bytes,logo_mime_type,logo_width,logo_height,logo_sha256,created_by) values(target_org,identity_version,logo,'image/jpeg',1280,692,encode(extensions.digest(logo,'sha256'),'hex'),owner_id) returning id into identity_id;update public.organizations set current_document_identity_id=identity_id where id=target_org;insert into public.audit_events(organization_id,actor_id,entity_type,entity_id,action,metadata) values(target_org,owner_id,'organization_document_identity',identity_id,'document_logo_added',jsonb_build_object('identity_version',identity_version,'mime_type','image/jpeg','width',1280,'height',692,'source','owner_provided'));end if;
end $$;

commit;
